// Trong SceneComposer.swift:
nonisolated static let minimumZoom: CGFloat = 1.0
nonisolated static let maximumZoom: CGFloat = 2.0

static func suggestedZoom(pose: ShootingPose, viewport: CGSize, availableDepth: CGFloat?, currentZoom: CGFloat) -> CGFloat {
    guard viewport.width > 0, availableDepth != nil else {
        return min(max(currentZoom, minimumZoom), maximumZoom)
    }
    let depth = max(availableDepth ?? 0, 0.5)
    let wantedDistance = pose.standoffInHeads * BodyPoseReference.typicalHeadHeight
    guard depth < wantedDistance else { return minimumZoom }
    return min(max(wantedDistance / depth, minimumZoom), maximumZoom)
}

