// Trong FigureAssetLoader.swift:
@MainActor
static func measureFigureHeight(_ entity: Entity) -> Float? {
    var meshes = 0
    var lowest = Float.greatestFiniteMagnitude
    var highest = -Float.greatestFiniteMagnitude
    func visit(_ node: Entity) {
        if node.components[ModelComponent.self] != nil {
            meshes += 1
            let box = node.visualBounds(relativeTo: nil)
            lowest = min(lowest, box.min.y)
            highest = max(highest, box.max.y)
        }
        for child in node.children { visit(child) }
    }
    visit(entity)
    guard meshes > 0, highest > lowest else { return nil }
    return highest - lowest
}

// Trong GuideCamera (TranslucentSceneView.swift):
static func position(for pose: ShootingPose) -> SIMD3<Float> {
    let distance = pose.cameraDistance
    let visibleHeight = 2 * distance * tan(Double.pi / 6)
    let frameCenterY = visibleHeight / 2
    return SIMD3<Float>(0, Float(frameCenterY), Float(distance))
}

static func target(for pose: ShootingPose) -> Entity {
    let distance = pose.cameraDistance
    let visibleHeight = 2 * distance * tan(Double.pi / 6)
    let target = Entity()
    target.position = SIMD3<Float>(0, Float(visibleHeight / 2), 0)
    return target
}

